def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 20.0))

    serious_prev = []
    max_prev = 0.0
    for oid, opp in alive:
        prev = opp.get('previous_trace', {})
        bid = None
        if prev:
            bid = prev.get('bid')
        if bid is not None:
            if bid > max_prev:
                max_prev = bid
            if bid > 0:
                serious_prev.append(float(bid))

    guaranteed_units = int(supply // WATER_REQ)
    contested = len(alive) + 1

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 1

    if guaranteed_units <= 1:
        urgency += 2
    elif guaranteed_units >= 2:
        urgency -= 1

    if contested >= 4:
        urgency += 1

    rich_threats = 0
    for oid, opp in alive:
        if opp.get('budget', 0) >= budget and opp.get('hp', 10) > 3:
            rich_threats += 1
    if rich_threats >= 2:
        urgency += 1

    if serious_prev:
        avg_prev = sum(serious_prev) / float(len(serious_prev))
    else:
        avg_prev = 0.0

    target = 0.0

    if urgency >= 5:
        target = max(90.0, max_prev + 1.5)
    elif urgency >= 3:
        if max_prev >= 85.0:
            target = max_prev + 1.0
        elif max_prev >= 60.0:
            target = max(72.0, max_prev + 2.0)
        else:
            target = 74.0
    elif urgency >= 1:
        if guaranteed_units >= 2:
            target = max(38.0, avg_prev * 0.75)
        else:
            target = max(52.0, min(78.0, max_prev * 0.9 + 3.0))
    else:
        if guaranteed_units >= 2:
            target = 26.0
        else:
            target = 42.0

    for oid, opp in alive:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            if prev.get('status') == 'won' and prev.get('bid') >= 85.0 and hp > 4 and no_water_days == 0:
                target = min(target, 35.0)

    if budget < target:
        if urgency >= 4:
            target = budget
        elif hp <= 3 or no_water_days >= 1:
            target = max(min(budget, 0.9 * budget), min(budget, 45.0))
        else:
            target = min(budget, 25.0)

    cap = budget
    if urgency <= 1 and hp >= 7:
        cap = min(cap, DAILY_SALARY * 0.9)
    elif urgency >= 5:
        cap = min(cap, 100.0)
    else:
        cap = min(cap, 95.0)

    bid = min(target, cap)
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Alive opponents
    alive_ids = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_ids.append(oid)

    if not alive_ids:
        # Conservative when alone
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Read yesterday bids and outcomes (immediate reaction)
    prev_bids = []
    prev_pressures = []
    for oid in alive_ids:
        prev = opponents_status[oid].get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    prev_bids.append(float(b))
                except Exception:
                    pass
            # pressure proxy: if they died yesterday, treat as high desperation signal
            if opponents_status[oid].get('hp', 0) < 0 or prev.get('hp_after', 0) is not None:
                # if yesterday led to death, they likely over/under bid; use their last bid as signal
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    # Cindy/Eric survived with ~83 average; use that as a contested benchmark
    contest_threshold = DAILY_SALARY * 0.92  # 82.8

    # Supply pressure: how many full requirements fit in total supply
    # If supply is scarce relative to water requirement, bidding competition increases.
    # Use ratio rather than floor to avoid float indexing.
    scarcity = (MAX_SUPPLY - supply) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY != MIN_SUPPLY else 0.0
    scarcity = max(0.0, min(1.0, float(scarcity)))

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])

    # Base willingness to pay: aim to beat typical surviving bids when contest is observed
    if highest_prev_bid >= contest_threshold:
        # They likely bid aggressively; if I'm healthy, undercut slightly; if low hp, match high
        if hp > 5.0:
            target = min(budget, (highest_prev_bid + 2.0) * (1.0 - 0.10 * scarcity))
        else:
            target = min(budget, highest_prev_bid + 3.0)
    else:
        # If no strong contest signal, bid enough to stay competitive under scarcity
        # Keep moderate so budget lasts 10 days.
        target = min(budget, DAILY_SALARY * (0.45 + 0.25 * scarcity))

    # If my hp is critical, prioritize survival regardless of contest
    if hp <= 2.0:
        target = min(budget, DAILY_SALARY * (0.85 + 0.10 * scarcity))

    # Ensure non-negative and at least a small bid if budget allows
    if target < 0.0:
        target = 0.0

    return float(target)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.3)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    bid = DAILY_SALARY * 0.55 # Default bid for healthy state, if no specific conditions met

    if not yesterday_bids:
        # No previous bids from opponents (e.g., Day 1 of the meta-round)
        if my_status['hp'] <= 2:
            bid = DAILY_SALARY * 0.9 # Critical HP, bid aggressively
        else:
            bid = DAILY_SALARY * 0.55 # Healthy HP, moderate bid
    else:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.85:
            # Opponents are bidding very high, indicating fierce competition
            if my_status['hp'] > 3:
                # If my HP is good, try to save money by bidding lower
                bid = DAILY_SALARY * 0.3
            else:
                # If my HP is low, I must bid very aggressively to survive
                bid = DAILY_SALARY * 0.95
        else:
            # Opponents are bidding moderately or low
            # Bid slightly above the highest previous bid, with a floor of DAILY_SALARY * 0.5
            bid = max(DAILY_SALARY * 0.5, highest_prev_bid + 1.5)

    # Ensure bid does not exceed available budget and is non-negative
    final_bid = min(my_status['budget'], bid)
    final_bid = max(0.0, final_bid)

    return final_bid
